import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Dashboard = ({ token, setToken }) => {
  const [ledgerData, setLedgerData] = useState({
    date: new Date().toISOString().split('T')[0],
    description: '',
    amount: '',
    category: 'expense'
  });
  const [entries, setEntries] = useState([]);
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [uploadFile, setUploadFile] = useState(null);
  const [stats, setStats] = useState({ total_count: 0, anomaly_count: 0 });

  const fetchEntries = async () => {
    if (!token) return;

    try {
      const response = await axios.get('http://localhost:5000/api/ledger', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setEntries(response.data.entries);
      setStats({
        total_count: response.data.total_count,
        anomaly_count: response.data.anomaly_count
      });
    } catch (error) {
      console.error('Failed to fetch entries:', error);
      if (error.response?.status === 401) {
        setToken(null);
      }
    }
  };

  useEffect(() => {
    if (token) {
      fetchEntries();
    }
  }, [token]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    try {
      const response = await axios.post('http://localhost:5000/api/ledger', ledgerData, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.is_anomaly) {
        setMessage({
          type: 'anomaly',
          text: `ANOMALY DETECTED! Entry added with ID ${response.data.entry_id}. Authority has been notified via email.`
        });
      } else {
        setMessage({
          type: 'success',
          text: `Entry added successfully with ID ${response.data.entry_id}`
        });
      }

      // Reset form
      setLedgerData({
        date: new Date().toISOString().split('T')[0],
        description: '',
        amount: '',
        category: 'expense'
      });

      // Refresh entries
      fetchEntries();
    } catch (error) {
      setMessage({
        type: 'error',
        text: error.response?.data?.error || 'Submission failed'
      });
    } finally {
      setLoading(false);
    }
  };

  const handleFileUpload = async (e) => {
    e.preventDefault();
    if (!uploadFile) {
      setMessage({ type: 'error', text: 'Please select a file' });
      return;
    }

    setLoading(true);
    setMessage('');

    const formData = new FormData();
    formData.append('file', uploadFile);

    try {
      const response = await axios.post('http://localhost:5000/api/upload-csv', formData, {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'multipart/form-data'
        }
      });

      if (response.data.anomaly_count > 0) {
        setMessage({
          type: 'anomaly',
          text: `File processed! ${response.data.anomaly_count} anomalies detected out of ${response.data.added_count} entries. Authorities notified.`
        });
      } else {
        setMessage({
          type: 'success',
          text: `File processed successfully! ${response.data.added_count} entries added, no anomalies detected.`
        });
      }

      setUploadFile(null);
      document.getElementById('fileInput').value = '';
      fetchEntries();
    } catch (error) {
      setMessage({
        type: 'error',
        text: error.response?.data?.error || 'Upload failed'
      });
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e) => {
    setLedgerData({
      ...ledgerData,
      [e.target.name]: e.target.value
    });
  };

  const handleLogout = () => {
    setToken(null);
  };

  return (
    <div className="main-content">
      {/* Header */}
      <div className="dashboard-header">
        <h1>Anomaly Detection System</h1>
        <div className="header-actions">
          <div className="stats-grid">
            <div className="stat-card">
              <div className="stat-number">{stats.total_count}</div>
              <div className="stat-label">Total Entries</div>
            </div>
            <div className="stat-card anomaly">
              <div className="stat-number">{stats.anomaly_count}</div>
              <div className="stat-label">Anomalies</div>
            </div>
          </div>
          <button onClick={handleLogout} className="btn btn-secondary">
            Logout
          </button>
        </div>
      </div>

      {/* Messages */}
      {message && (
        <div className={`message ${message.type}`}>
          {message.text}
        </div>
      )}

      {/* File Upload Card */}
      <div className="card">
        <div className="card-header">
          <h2>📁 Bulk Upload</h2>
        </div>
        <div className="card-body">
          <form onSubmit={handleFileUpload}>
            <div className="form-group">
              <label>Select CSV File</label>
              <input
                id="fileInput"
                type="file"
                accept=".csv"
                onChange={(e) => setUploadFile(e.target.files[0])}
                className="form-input"
              />
              <small className="help-text">
                Required columns: date, description, amount, category
              </small>
            </div>
            <button type="submit" className="btn btn-primary" disabled={loading}>
              {loading ? 'Processing...' : 'Upload & Analyze'}
            </button>
          </form>
        </div>
      </div>

      {/* Manual Entry Card */}
      <div className="card">
        <div className="card-header">
          <h2>✏️ Manual Entry</h2>
        </div>
        <div className="card-body">
          <form onSubmit={handleSubmit}>
            <div className="form-grid">
              <div className="form-group">
                <label>Date</label>
                <input
                  type="date"
                  name="date"
                  value={ledgerData.date}
                  onChange={handleChange}
                  required
                  className="form-input"
                />
              </div>
              <div className="form-group">
                <label>Category</label>
                <select
                  name="category"
                  value={ledgerData.category}
                  onChange={handleChange}
                  required
                  className="form-select"
                >
                  <option value="expense">Expense</option>
                  <option value="income">Income</option>
                  <option value="transfer">Transfer</option>
                  <option value="investment">Investment</option>
                  <option value="loan">Loan</option>
                  <option value="other">Other</option>
                </select>
              </div>
              <div className="form-group">
                <label>Amount (₹)</label>
                <input
                  type="number"
                  step="0.01"
                  name="amount"
                  value={ledgerData.amount}
                  onChange={handleChange}
                  required
                  placeholder="Enter amount"
                  className="form-input"
                />
              </div>
            </div>
            <div className="form-group">
              <label>Description</label>
              <textarea
                name="description"
                value={ledgerData.description}
                onChange={handleChange}
                required
                placeholder="Enter transaction description"
                className="form-textarea"
                rows="3"
              />
            </div>
            <button type="submit" className="btn btn-primary" disabled={loading}>
              {loading ? 'Processing...' : 'Submit Entry'}
            </button>
          </form>
        </div>
      </div>

      {/* Entries Table */}
      <div className="card">
        <div className="card-header">
          <h2>📊 Recent Entries</h2>
        </div>
        <div className="card-body">
          {entries.length === 0 ? (
            <div className="empty-state">
              <p>No entries found. Add your first transaction!</p>
            </div>
          ) : (
            <div className="table-container">
              <table className="entries-table">
                <thead>
                  <tr>
                    <th>Date</th>
                    <th>Description</th>
                    <th>Amount</th>
                    <th>Category</th>
                    <th>Status</th>
                    <th>Created</th>
                  </tr>
                </thead>
                <tbody>
                  {entries.map((entry) => (
                    <tr key={entry.id} className={entry.is_anomaly ? 'anomaly-row' : ''}>
                      <td>{entry.date}</td>
                      <td>{entry.description}</td>
                      <td>₹{parseFloat(entry.amount).toLocaleString('en-IN', {minimumFractionDigits: 2})}</td>
                      <td className="category">{entry.category}</td>
                      <td>
                        {entry.is_anomaly ? (
                          <span className="anomaly-badge">ANOMALY</span>
                        ) : (
                          <span className="normal-badge">NORMAL</span>
                        )}
                      </td>
                      <td>{new Date(entry.created_at).toLocaleString()}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
